    49→  public static getOrCreateDirectRoom = async (
    50→    userId: string,
    51→  ): Promise<string> => {
    52→    const client = MatrixCore.getClient();
    53→
    54→    try {
    55→      const existingRoomId = await this.getExistingDirectRoom(userId);
    56→      if (existingRoomId) return existingRoomId;
    57→
    58→      const roomOptions: CreateRoomParameters = {
    59→        name: undefined,
    60→        topic: undefined,
    61→        preset: RoomPreset.PrivateChat,
    62→        avatar: undefined,
    63→        isEncrypted: true,
    64→        isDirect: true,
    65→        visibility: new RoomVisibility.Private(),
    66→        invite: [userId],
    67→        powerLevelContentOverride: undefined,
    68→        joinRuleOverride: undefined,
    69→        historyVisibilityOverride: undefined,
    70→        canonicalAlias: undefined,
    71→      };
    72→
    73→      const roomId = await client.createRoom(roomOptions);
    74→      await MatrixCore.refreshRoomList();
    75→      return roomId;
    76→    } catch (error) {
    77→      throw new Error(`Failed to get or create direct room: ${error}`);
