     1→import { Screen } from "@prototyp/skeletor";
     2→import type { NativeStackScreenProps } from "@react-navigation/native-stack";
     3→import {
     4→  Membership,
     5→  type RoomInfo,
     6→  StateEventType,
     7→} from "@unomed/react-native-matrix-sdk";
     8→import { ElementCallService } from "modules/call/service";
     9→import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
    10→import { useRoomInitialization } from "modules/timeline/hooks";
    11→import { useEffect, useMemo, useState } from "react";
    12→import { useSafeAreaInsets } from "react-native-safe-area-context";
    13→import { Loading } from "shared/components";
    14→import { RoomHeader, RoomInvite, RoomTimeline } from "./fragments";
    15→
    16→export const Room: React.FC<NativeStackScreenProps<Routes, "room">> = ({
    17→  route,
    18→  navigation,
    19→}) => {
    20→  const { roomId } = route.params;
    21→  const client = MatrixCore.instance;
    22→  const room = useMemo(() => client?.getRoom(roomId), [client, roomId]);
    23→  const insets = useSafeAreaInsets();
    24→  const [roomInfo, setRoomInfo] = useState<RoomInfo | undefined>(undefined);
    25→  const [isInviteAccepted, setIsInviteAccepted] = useState(false);
    26→  const isRoomInvite = useMemo(() => {
    27→    return roomInfo?.membership === Membership.Invited && !isInviteAccepted;
    28→  }, [roomInfo, isInviteAccepted]);
    29→  const hasOngoingCall = roomInfo?.hasRoomCall ?? false;
    30→  const activeCallRoomId = ElementCallService.getActiveCallRoomId();
    31→  const isParticipatingInOngoingCall =
    32→    !!activeCallRoomId && activeCallRoomId !== roomId;
    33→  const canJoinCall =
    34→    roomInfo?.powerLevels?.canOwnUserSendState(StateEventType.CallMember) ??
    35→    false;
    36→
    37→  const { isMembersLoading, roomMembers } = useRoomInitialization({ room });
    38→
    39→  useEffect(() => {
    40→    room?.roomInfo().then(setRoomInfo).catch(console.error);
    41→  }, [room]);
    42→
    43→  const handleStartCall = () => {
    44→    if (!client || !room) {
    45→      console.error("Client or room not available");
    46→      return;
    47→    }
    48→
    49→    navigation.navigate("elementCall", {
    50→      roomId,
    51→      roomName: room.displayName(),
    52→    });
    53→  };
    54→
    55→  const handleInviteAccepted = () => {
    56→    setIsInviteAccepted(true);
    57→  };
    58→
    59→  const handleInviteDeclined = () => {
    60→    navigation.goBack();
    61→  };
    62→
    63→  const handleRoomDetails = () => {
    64→    if (isRoomInvite || !room) return;
    65→    navigation.navigate("roomDetails", { room });
    66→  };
    67→
    68→  if (!room) return null;
    69→
    70→  if (!roomInfo) {
    71→    return (
    72→      <Screen hideTopSafeArea scrollable={false}>
    73→        <RoomHeader
    74→          room={room}
    75→          isMembersLoading={isMembersLoading}
    76→          roomMembers={roomMembers}
    77→          hasNoCallOption
    78→          topInset={insets.top}
    79→          onBack={() => navigation.goBack()}
    80→        />
    81→        <Loading isFullScreen={false} />
    82→      </Screen>
    83→    );
    84→  }
    85→
    86→  return (
    87→    <Screen hideTopSafeArea>
    88→      <RoomHeader
    89→        room={room}
    90→        isMembersLoading={isMembersLoading}
    91→        roomMembers={roomMembers}
    92→        hasNoCallOption={isRoomInvite}
    93→        hasOngoingCall={hasOngoingCall}
    94→        isParticipatingInOngoingCall={isParticipatingInOngoingCall}
    95→        canJoinCall={canJoinCall}
    96→        topInset={insets.top}
    97→        onBack={() => navigation.goBack()}
    98→        onRoomDetails={handleRoomDetails}
    99→        onStartCall={handleStartCall}
   100→      />
   101→
   102→      {isRoomInvite ? (
   103→        <RoomInvite
   104→          roomId={roomId}
   105→          roomInfo={roomInfo}
   106→          onAccepted={handleInviteAccepted}
   107→          onDeclined={handleInviteDeclined}
   108→        />
   109→      ) : (
   110→        <RoomTimeline room={room} roomId={roomId} />
   111→      )}
   112→    </Screen>
   113→  );
   114→};
