    49→export const RoomTimeline: FC<Props> = ({ room, roomId }) => {
    50→  const flatListRef = useRef<FlashListRef<TimelineListItem>>(null);
    51→  const isAtBottomRef = useRef(true);
    52→  const lastEventKeyRef = useRef<string | undefined>(undefined);
    53→  const [showScrollDown, setShowScrollDown] = useState(false);
    54→  const {
    55→    events,
    56→    loadingMessage,
    57→    refreshing,
    58→    updateTrigger,
    59→    isDirect,
    60→    loadMoreMessages,
    61→    markAsRead,
    62→  } = useRoomTimeline({
    63→    room,
    64→    roomId,
    65→  });
    66→  const [scrollToEventId, setScrollToEventId] = useAtom(
    67→    TimelineAtoms.scrollToEventId,
    68→  );
    69→  const {
    70→    selectedMember,
    71→    isBottomSheetOpen,
    72→    openMemberDetails,
    73→    closeMemberDetails,
