   133→
   134→  const handleContentSizeChange = () => {
   135→    const lastEvent = sortedEvents[sortedEvents.length - 1];
   136→    const lastEventKey = lastEvent
   137→      ? (getItemUniqueKey(lastEvent) ?? undefined)
   138→      : undefined;
   139→    const isNewEvent = lastEventKey !== lastEventKeyRef.current;
   140→    lastEventKeyRef.current = lastEventKey;
   141→    if (!isNewEvent || !lastEvent?.isOwn) return;
