   167→          maintainVisibleContentPosition={{
   168→            startRenderingFromBottom: true,
   169→          }}
   170→          extraData={updateTrigger}
   171→          contentContainerStyle={styles.listContent}
   172→          refreshing={refreshing}
   173→          onContentSizeChange={handleContentSizeChange}
   174→          onRefresh={handleLoadMore}
   175→          onScroll={handleOnScroll}
